/*
 * FrostCore -- Stage 3: Bytecode IR header
 *
 * frost_bytecode is a self-contained, portable binary blob produced by
 * frost_parse(). It contains no pointers into any JSRuntime -- it is safe
 * to cache on disk, send across processes, or load into multiple runtimes.
 *
 * The blob format is quickjs-ng's native serialisation (JS_WriteObject /
 * JS_ReadObject with JS_WRITE_OBJ_BYTECODE). Atom indices are remapped
 * during serialisation so the blob is runtime-independent.
 *
 * GlacioJS treats this as completely opaque. Only use the functions in
 * frostcore.h to inspect or execute it.
 */
#ifndef FROST_BYTECODE_H
#define FROST_BYTECODE_H

#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

/* -----------------------------------------------------------------------
 * frost_bytecode -- opaque compiled JS
 *
 * Fields are intentionally hidden; use frost_bytecode_size() to measure.
 * ----------------------------------------------------------------------- */
typedef struct frost_bytecode frost_bytecode;

/* -----------------------------------------------------------------------
 * frost_error -- parse/load error descriptor
 *
 * line and column are 1-based; 0 means not available.
 * message is a system-malloc'd NUL-terminated UTF-8 string.
 * Call frost_error_free() or just free(message) when done.
 * ----------------------------------------------------------------------- */
typedef struct frost_error {
    char   *message;   /* malloc'd -- caller must free */
    int     line;
    int     column;
} frost_error;

static inline void frost_error_free(frost_error *e)
{
    if (e) {
        /* free is always system malloc -- frost_bytecode uses system alloc
           internally for the error string even on custom-alloc runtimes */
        extern void free(void *);
        free(e->message);
        e->message = (void *)0;
        e->line    = 0;
        e->column  = 0;
    }
}

/* Size of the serialised blob in bytes -- useful for cache accounting */
size_t frost_bytecode_size(const frost_bytecode *bc);

#ifdef __cplusplus
}
#endif

#endif /* FROST_BYTECODE_H */

