/*
 * FrostCore -- Stage 3: Parser boundary
 *
 * frost_parse() compiles JS source to a portable bytecode blob without
 * keeping any runtime alive. It does so by:
 *   1. Spinning up a minimal scratch JSRuntime + JSContext (system alloc).
 *   2. Calling JS_Eval with JS_EVAL_FLAG_COMPILE_ONLY to get a function obj.
 *   3. Serialising the function obj via JS_WriteObject (self-contained blob).
 *   4. Tearing down the scratch runtime -- the blob has no dangling pointers.
 *
 * frost_bytecode_destroy() frees the blob independently of any runtime.
 */
#include "frostcore.h"
#include "frost_bytecode.h"

#include "quickjs.h"

#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* -----------------------------------------------------------------------
 * Internal struct
 *
 * The blob is the raw bytes from JS_WriteObject. We keep size separately
 * so frost_bytecode_size() doesn't need to scan the blob.
 * ----------------------------------------------------------------------- */
struct frost_bytecode {
    uint8_t *blob;
    size_t   size;
};

/* -----------------------------------------------------------------------
 * frost_bytecode_size
 * ----------------------------------------------------------------------- */
size_t frost_bytecode_size(const frost_bytecode *bc)
{
    return bc ? bc->size : 0;
}

/* -----------------------------------------------------------------------
 * frost_bytecode_destroy
 * ----------------------------------------------------------------------- */
void frost_bytecode_destroy(frost_bytecode *bc)
{
    if (!bc) return;
    /* JS_WriteObject allocates with js_malloc internally and returns a
       pointer freed via js_free(rt,...). Since the scratch runtime is
       already destroyed at this point, JS gave us a plain malloc'd buffer
       (quickjs-ng uses the system allocator for WriteObject output).
       We free it with the system free(). */
    free(bc->blob);
    free(bc);
}

/* -----------------------------------------------------------------------
 * Internal: extract error message + location from an exception in ctx.
 * Fills err if non-NULL. Always clears the pending exception.
 * ----------------------------------------------------------------------- */
static void extract_error(JSContext *ctx, frost_error *err)
{
    JSValue exc = JS_GetException(ctx);

    if (!err) {
        JS_FreeValue(ctx, exc);
        return;
    }

    err->message = NULL;
    err->line    = 0;
    err->column  = 0;

    /* Try to get .message property first, fall back to toString() */
    JSValue msg_val = JS_GetPropertyStr(ctx, exc, "message");
    const char *msg = NULL;

    if (!JS_IsUndefined(msg_val) && !JS_IsException(msg_val))
        msg = JS_ToCString(ctx, msg_val);

    if (!msg) {
        JS_FreeValue(ctx, msg_val);
        msg_val = JS_UNDEFINED;
        msg = JS_ToCString(ctx, exc);
    }

    if (msg) {
        size_t n = strlen(msg) + 1;
        err->message = (char *)malloc(n);
        if (err->message) memcpy(err->message, msg, n);
        JS_FreeCString(ctx, msg);
    }
    JS_FreeValue(ctx, msg_val);

    /* Try to get line number from .stack or .lineNumber */
    JSValue line_val = JS_GetPropertyStr(ctx, exc, "lineNumber");
    if (!JS_IsUndefined(line_val) && !JS_IsException(line_val)) {
        int32_t ln = 0;
        if (JS_ToInt32(ctx, &ln, line_val) == 0)
            err->line = (int)ln;
    }
    JS_FreeValue(ctx, line_val);

    JS_FreeValue(ctx, exc);
}

/* -----------------------------------------------------------------------
 * frost_parse
 * ----------------------------------------------------------------------- */
int frost_parse(const char *source, const char *filename,
                frost_bytecode **out, frost_error *err)
{
    if (out) *out = NULL;
    if (err) { err->message = NULL; err->line = 0; err->column = 0; }

    if (!source || !out) return -1;

    const char *fname = filename ? filename : "<frost_parse>";

    /* -- Scratch runtime (system alloc, torn down after serialisation) -- */
    JSRuntime *rt = JS_NewRuntime();
    if (!rt) {
        if (err) {
            err->message = (char *)malloc(32);
            if (err->message) memcpy(err->message, "OOM: JS_NewRuntime", 19);
        }
        return -1;
    }

    JSContext *ctx = JS_NewContext(rt);
    if (!ctx) {
        JS_FreeRuntime(rt);
        if (err) {
            err->message = (char *)malloc(32);
            if (err->message) memcpy(err->message, "OOM: JS_NewContext", 19);
        }
        return -1;
    }

    /* -- Compile only (no execution) -- */
    size_t src_len = strlen(source);
    JSValue fn = JS_Eval(ctx, source, src_len, fname,
                         JS_EVAL_TYPE_GLOBAL | JS_EVAL_FLAG_COMPILE_ONLY);

    if (JS_IsException(fn)) {
        extract_error(ctx, err);
        JS_FreeContext(ctx);
        JS_FreeRuntime(rt);
        return -1;
    }

    /* -- Serialise to self-contained blob -- */
    size_t blob_size = 0;
    uint8_t *blob = JS_WriteObject(ctx, &blob_size, fn,
                                   JS_WRITE_OBJ_BYTECODE |
                                   JS_WRITE_OBJ_STRIP_SOURCE);

    JS_FreeValue(ctx, fn);

    if (!blob) {
        if (err) {
            const char *msg = "JS_WriteObject failed";
            size_t n = strlen(msg) + 1;
            err->message = (char *)malloc(n);
            if (err->message) memcpy(err->message, msg, n);
        }
        JS_FreeContext(ctx);
        JS_FreeRuntime(rt);
        return -1;
    }

    /* -- Copy blob out before destroying the runtime --
       JS_WriteObject allocates via the runtime's allocator. We need a
       copy that outlives the runtime. */
    uint8_t *owned = (uint8_t *)malloc(blob_size);
    if (!owned) {
        js_free(ctx, blob);
        JS_FreeContext(ctx);
        JS_FreeRuntime(rt);
        if (err) {
            err->message = (char *)malloc(32);
            if (err->message) memcpy(err->message, "OOM: blob copy", 15);
        }
        return -1;
    }
    memcpy(owned, blob, blob_size);
    js_free(ctx, blob);

    JS_FreeContext(ctx);
    JS_FreeRuntime(rt);

    /* -- Wrap in frost_bytecode -- */
    frost_bytecode *bc = (frost_bytecode *)malloc(sizeof(frost_bytecode));
    if (!bc) {
        free(owned);
        if (err) {
            err->message = (char *)malloc(32);
            if (err->message) memcpy(err->message, "OOM: frost_bytecode", 20);
        }
        return -1;
    }
    bc->blob = owned;
    bc->size = blob_size;

    *out = bc;
    return 0;
}

/*
 * FrostCore -- Stage 3: VM load/eval boundary
 *
 * frost_runtime_load() deserialises a frost_bytecode blob into a runtime,
 * storing the resulting JSValue function handle for later execution.
 * The same bytecode blob may be loaded into multiple runtimes concurrently.
 *
 * frost_runtime_eval_loaded() executes the function handle that was stored
 * by frost_runtime_load() on the same runtime. May be called multiple times.
 *
 * Internal design:
 *   The loaded JSValue is stored in frost_runtime.loaded_fn. This is a
 *   reference-counted QuickJS value owned by the context. frost_runtime_destroy
 *   frees it via JS_FreeValue if it has been set.
 */
#include "frostcore.h"

#include "quickjs.h"

#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* -----------------------------------------------------------------------
 * Internal accessors -- implemented in frostcore.c
 * ----------------------------------------------------------------------- */
JSContext    *frost_internal_ctx(frost_runtime *rt);
unsigned int *frost_internal_reg(frost_runtime *rt);
JSValue      *frost_internal_loaded_fn(frost_runtime *rt);

/* -----------------------------------------------------------------------
 * Internal: format a C-string error from a pending JS exception.
 * Clears the exception. Returns malloc'd string; caller must free.
 * ----------------------------------------------------------------------- */
static char *vm_extract_error(JSContext *ctx)
{
    JSValue exc = JS_GetException(ctx);

    /* Try .message first, fall back to toString */
    JSValue msg_val = JS_GetPropertyStr(ctx, exc, "message");
    const char *msg = NULL;

    if (!JS_IsUndefined(msg_val) && !JS_IsException(msg_val))
        msg = JS_ToCString(ctx, msg_val);

    if (!msg) {
        JS_FreeValue(ctx, msg_val);
        msg_val = JS_UNDEFINED;
        msg = JS_ToCString(ctx, exc);
    }

    char *result = NULL;
    if (msg) {
        size_t n = strlen(msg) + 1;
        result = (char *)malloc(n);
        if (result) memcpy(result, msg, n);
        JS_FreeCString(ctx, msg);
    } else {
        const char *fallback = "unknown JS error";
        size_t n = strlen(fallback) + 1;
        result = (char *)malloc(n);
        if (result) memcpy(result, fallback, n);
    }

    JS_FreeValue(ctx, msg_val);
    JS_FreeValue(ctx, exc);
    return result;
}

/* -----------------------------------------------------------------------
 * frost_runtime_load
 *
 * Deserialises bc->blob into the runtime's context. The resulting
 * JSValue function is stored in rt->loaded_fn. Any previously loaded
 * function is released first (idempotent -- load can be called again
 * to replace the currently loaded bytecode).
 * ----------------------------------------------------------------------- */
int frost_runtime_load(frost_runtime *rt, const frost_bytecode *bc,
                       char **out_error)
{
    if (out_error) *out_error = NULL;
    if (!rt || !bc) return -1;

    JSContext *ctx = frost_internal_ctx(rt);
    if (!ctx) return -1;

    const uint8_t *blob = NULL;
    size_t         blob_size = 0;

    /* Access blob fields -- frost_bytecode is defined in frost_parse.c.
       We reach them via frost_bytecode_size() for the size, and we need
       a way to get the raw pointer. Expose it via an internal accessor. */
    blob_size = frost_bytecode_size(bc);
    if (blob_size == 0) {
        if (out_error) {
            const char *msg = "empty bytecode blob";
            size_t n = strlen(msg) + 1;
            *out_error = (char *)malloc(n);
            if (*out_error) memcpy(*out_error, msg, n);
        }
        return -1;
    }

    /* frost_bytecode_data() is an internal accessor we add below */
    extern const uint8_t *frost_bytecode_data(const frost_bytecode *bc);
    blob = frost_bytecode_data(bc);

    /* Release any previously loaded function */
    JSValue *loaded = frost_internal_loaded_fn(rt);
    if (!JS_IsUndefined(*loaded) && !JS_IsNull(*loaded))
        JS_FreeValue(ctx, *loaded);
    *loaded = JS_UNDEFINED;

    /* Deserialise */
    JSValue fn = JS_ReadObject(ctx, blob, blob_size, JS_READ_OBJ_BYTECODE);

    if (JS_IsException(fn)) {
        if (out_error)
            *out_error = vm_extract_error(ctx);
        else
            JS_GetException(ctx); /* clear it */
        return -1;
    }

    *loaded = fn;
    return 0;
}

/* -----------------------------------------------------------------------
 * frost_runtime_eval_loaded
 *
 * Executes the function stored by frost_runtime_load() on this runtime.
 * JS_EvalFunction() consumes (frees) the JSValue, so we must duplicate
 * it first so the same loaded_fn can be executed multiple times.
 * ----------------------------------------------------------------------- */
int frost_runtime_eval_loaded(frost_runtime *rt, const frost_bytecode *bc,
                              char **out_error)
{
    (void)bc; /* bc is unused here -- the loaded fn is tracked per-runtime */
    if (out_error) *out_error = NULL;
    if (!rt) return -1;

    JSContext *ctx = frost_internal_ctx(rt);
    if (!ctx) return -1;

    JSValue *loaded = frost_internal_loaded_fn(rt);
    if (JS_IsUndefined(*loaded) || JS_IsNull(*loaded)) {
        if (out_error) {
            const char *msg = "no bytecode loaded -- call frost_runtime_load first";
            size_t n = strlen(msg) + 1;
            *out_error = (char *)malloc(n);
            if (*out_error) memcpy(*out_error, msg, n);
        }
        return -1;
    }

    /* Duplicate so EvalFunction doesn't consume our stored reference */
    JSValue fn_dup = JS_DupValue(ctx, *loaded);

    JSValue result = JS_EvalFunction(ctx, fn_dup);

    if (JS_IsException(result)) {
        if (out_error)
            *out_error = vm_extract_error(ctx);
        else
            JS_GetException(ctx); /* clear it */
        JS_FreeValue(ctx, result);
        return -1;
    }

    JS_FreeValue(ctx, result);
    return 0;
}

