211	    size_t len = strlen(source);
212	    JSValue result = JS_Eval(rt->js_ctx, source, len, "<frost>", JS_EVAL_TYPE_GLOBAL);
213	
214	    if (!JS_IsException(result)) {
215	        JS_FreeValue(rt->js_ctx, result);
216	        return 0;
217	    }
218	
