220	    JSValue exc = JS_GetException(rt->js_ctx);
221	
222	    if (out_error) {
223	        const char *msg = JS_ToCString(rt->js_ctx, exc);
224	        if (msg) {
225	            *out_error = (char *)malloc(strlen(msg) + 1);
226	            if (*out_error) memcpy(*out_error, msg, strlen(msg) + 1);
227	            JS_FreeCString(rt->js_ctx, msg);
228	        }
229	    }
230	
231	    JS_FreeValue(rt->js_ctx, exc);
232	    return -1;
233	}
234	
235	/* -----------------------------------------------------------------------
