void frost_runtime_destroy(frost_runtime *rt)
{
    if (!rt) return;
    void (*free_fn)(void *, void *) = rt->alloc.free;
    void *userdata                  = rt->alloc.userdata;

    /* Release any loaded bytecode function before tearing down the context */
    if (rt->js_ctx && !JS_IsUndefined(rt->loaded_fn) && !JS_IsNull(rt->loaded_fn))
