arguments.content:
/*
 * FrostCore Stage 3 -- Bytecode boundary test suite
 *
 * Groups:
 *   B1  frost_parse basic success
 *   B2  frost_bytecode_size
 *   B3  frost_parse error cases
 *   B4  frost_bytecode_destroy edge cases
 *   B5  frost_runtime_load basic
 *   B6  frost_runtime_eval_loaded basic
 *   B7  parse-once-run-many (same bytecode, multiple runtimes)
 *   B8  bytecode independence (parse runtime torn down, blob still works)
 *   B9  frost_runtime_load into bare runtime
 *   B10 frost_runtime_eval_loaded multiple times on same runtime
 *   B11 frost_runtime_load replaces previous load
 *   B12 frost_runtime_eval_loaded before load (error)
 *   B13 frost_runtime_load NULL / bad args
 */
#include "frostcore.h"
#include "frostcore_subsystems.h"
#include "frost_bytecode.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* -----------------------------------------------------------------------
 * Minimal test harness
 * ----------------------------------------------------------------------- */
static int g_pass = 0;
static int g_fail = 0;

#define PASS() do { g_pass++; } while(0)

#define FAIL(fmt, ...) do { \
    printf("  FAIL %s:%d -- " fmt "\n", __FILE__, __LINE__, ##__VA_ARGS__); \
    fflush(stdout); \
    g_fail++; \
} while(0)

#define CHECK(cond) do { \
    if (cond) { PASS(); } \
    else { FAIL("CHECK(%s)", #cond); } \
} while(0)

#define CHECK_EQ(a, b) do { \
    if ((a) == (b)) { PASS(); } \
    else { FAIL("CHECK_EQ(%s, %s) -- %lld != %lld", \
        #a, #b, (long long)(a), (long long)(b)); } \
} while(0)

#define CHECK_NULL(p) do { \
    if ((p) == NULL) { PASS(); } \
    else { FAIL("CHECK_NULL(%s) -- was non-null", #p); } \
} while(0)

#define CHECK_NOTNULL(p) do { \
    if ((p) != NULL) { PASS(); } \
    else { FAIL("CHECK_NOTNULL(%s) -- was NULL", #p); } \
} while(0)

#define CHECK_STR_CONTAINS(str, sub) do { \
    if ((str) && strstr((str), (sub))) { PASS(); } \
    else { FAIL("CHECK_STR_CONTAINS: \"%s\" not in \"%s\"", \
        (sub), (str) ? (str) : "(null)"); } \
} while(0)

static void group(const char *name)
{
    printf("\n--- %s ---\n", name);
    fflush(stdout);
}

/* -----------------------------------------------------------------------
 * Helpers
 * ----------------------------------------------------------------------- */
static frost_runtime *make_full(void)
{
    return frost_runtime_create(NULL);
}

static frost_runtime *make_bare_with_core(void)
{
    frost_runtime *rt = frost_runtime_create_bare(NULL);
    if (!rt) return NULL;
    char *err = NULL;
    if (frost_register_std_core(rt, &err) != 0) {
        free(err);
        frost_runtime_destroy(rt);
        return NULL;
    }
    return rt;
}

/* -----------------------------------------------------------------------
 * B1 -- frost_parse basic success
 * ----------------------------------------------------------------------- */
static void test_B1(void)
{
    group("B1: frost_parse basic success");

    frost_bytecode *bc = NULL;
    frost_error err = {NULL, 0, 0};

    int rc = frost_parse("var x = 1 + 2;", "test.js", &bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NOTNULL(bc);
    CHECK_NULL(err.message);
    CHECK_EQ(err.line, 0);

    frost_bytecode_destroy(bc);
    frost_error_free(&err);
}

static void test_B1b(void)
{
    /* Parse with NULL filename -- should use default */
    frost_bytecode *bc = NULL;
    int rc = frost_parse("function foo() { return 42; }", NULL, &bc, NULL);
    CHECK_EQ(rc, 0);
    CHECK_NOTNULL(bc);
    frost_bytecode_destroy(bc);
}

static void test_B1c(void)
{
    /* Parse more complex source */
    const char *src =
        "var arr = [1,2,3];"
        "var sum = arr.reduce(function(a,b){return a+b;}, 0);"
        "sum;";
    frost_bytecode *bc = NULL;
    int rc = frost_parse(src, "complex.js", &bc, NULL);
    CHECK_EQ(rc, 0);
    CHECK_NOTNULL(bc);
    frost_bytecode_destroy(bc);
}

/* -----------------------------------------------------------------------
 * B2 -- frost_bytecode_size
 * ----------------------------------------------------------------------- */
static void test_B2(void)
{
    group("B2: frost_bytecode_size");

    frost_bytecode *bc = NULL;
    int rc = frost_parse("var x = 1;", "t.js", &bc, NULL);
    CHECK_EQ(rc, 0);
    CHECK_NOTNULL(bc);

    size_t sz = frost_bytecode_size(bc);
    CHECK(sz > 0);

    /* Larger source should produce larger (or equal) bytecode */
    frost_bytecode *bc2 = NULL;
    frost_parse("var a=1;var b=2;var c=3;var d=4;var e=5;", "t2.js", &bc2, NULL);
    if (bc2) {
        size_t sz2 = frost_bytecode_size(bc2);
        CHECK(sz2 > 0);
        frost_bytecode_destroy(bc2);
    }

    frost_bytecode_destroy(bc);

    /* NULL safety */
    CHECK_EQ(frost_bytecode_size(NULL), 0);
}

/* -----------------------------------------------------------------------
 * B3 -- frost_parse error cases
 * ----------------------------------------------------------------------- */
static void test_B3(void)
{
    group("B3: frost_parse error cases");

    frost_bytecode *bc = NULL;
    frost_error err = {NULL, 0, 0};

    /* Syntax error */
    int rc = frost_parse("var x = ;", "bad.js", &bc, &err);
    CHECK_EQ(rc, -1);
    CHECK_NULL(bc);
    CHECK_NOTNULL(err.message);  /* should have an error message */
    CHECK(err.line > 0 || err.message != NULL);  /* line may or may not be filled */
    frost_error_free(&err);

    /* NULL source */
    rc = frost_parse(NULL, "x.js", &bc, &err);
    CHECK_EQ(rc, -1);
    frost_error_free(&err);

    /* NULL out */
    rc = frost_parse("var x = 1;", "x.js", NULL, &err);
    CHECK_EQ(rc, -1);
    frost_error_free(&err);

    /* Unclosed brace */
    bc = NULL;
    err.message = NULL; err.line = 0; err.column = 0;
    rc = frost_parse("function f() {", "unc.js", &bc, &err);
    CHECK_EQ(rc, -1);
    CHECK_NULL(bc);
    frost_error_free(&err);

    /* err may be NULL -- should not crash */
    bc = NULL;
    rc = frost_parse("var x = ;", "bad2.js", &bc, NULL);
    CHECK_EQ(rc, -1);
    CHECK_NULL(bc);
}

/* -----------------------------------------------------------------------
 * B4 -- frost_bytecode_destroy edge cases
 * ----------------------------------------------------------------------- */
static void test_B4(void)
{
    group("B4: frost_bytecode_destroy edge cases");

    /* NULL -- must not crash */
    frost_bytecode_destroy(NULL);
    PASS();

    /* Normal destroy */
    frost_bytecode *bc = NULL;
    frost_parse("1+1;", "t.js", &bc, NULL);
    if (bc) {
        frost_bytecode_destroy(bc);
        PASS();
    }
}

/* -----------------------------------------------------------------------
 * B5 -- frost_runtime_load basic
 * ----------------------------------------------------------------------- */
static void test_B5(void)
{
    group("B5: frost_runtime_load basic");

    frost_bytecode *bc = NULL;
    int rc = frost_parse("var loaded = true;", "load.js", &bc, NULL);
    CHECK_EQ(rc, 0);
    CHECK_NOTNULL(bc);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    rc = frost_runtime_load(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc);

    /* NULL runtime */
    rc = frost_runtime_load(NULL, bc, &err);
    CHECK_EQ(rc, -1);
    free(err);

    /* NULL bytecode */
    rt = make_full();
    rc = frost_runtime_load(rt, NULL, &err);
    CHECK_EQ(rc, -1);
    frost_runtime_destroy(rt);
    free(err);
}

/* -----------------------------------------------------------------------
 * B6 -- frost_runtime_eval_loaded basic
 * ----------------------------------------------------------------------- */
static void test_B6(void)
{
    group("B6: frost_runtime_eval_loaded basic");

    frost_bytecode *bc = NULL;
    frost_parse("var result = 6 * 7;", "eval.js", &bc, NULL);
    CHECK_NOTNULL(bc);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc, &err);
    CHECK_EQ(rc, 0);

    rc = frost_runtime_eval_loaded(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc);
}

/* -----------------------------------------------------------------------
 * B7 -- parse-once-run-many (same bytecode, multiple runtimes)
 * ----------------------------------------------------------------------- */
static void test_B7(void)
{
    group("B7: parse-once-run-many");

    /* Parse once */
    frost_bytecode *bc = NULL;
    int rc = frost_parse("var x = 100;", "once.js", &bc, NULL);
    CHECK_EQ(rc, 0);
    CHECK_NOTNULL(bc);

    /* Load and eval in 5 separate runtimes */
    for (int i = 0; i < 5; i++) {
        frost_runtime *rt = make_full();
        CHECK_NOTNULL(rt);

        char *err = NULL;
        rc = frost_runtime_load(rt, bc, &err);
        CHECK_EQ(rc, 0);
        CHECK_NULL(err);

        rc = frost_runtime_eval_loaded(rt, bc, &err);
        CHECK_EQ(rc, 0);
        CHECK_NULL(err);

        frost_runtime_destroy(rt);
    }

    frost_bytecode_destroy(bc);
}

/* -----------------------------------------------------------------------
 * B8 -- bytecode independence from parse runtime
 *
 * After frost_parse() returns, the scratch runtime is destroyed.
 * The blob must still work loaded into a fresh runtime.
 * ----------------------------------------------------------------------- */
static void test_B8(void)
{
    group("B8: bytecode independence from parse runtime");

    frost_bytecode *bc = NULL;
    {
        frost_error err = {NULL, 0, 0};
        int rc = frost_parse("var independence = 1;", "indep.js", &bc, &err);
        CHECK_EQ(rc, 0);
        CHECK_NOTNULL(bc);
        frost_error_free(&err);
        /* Scratch runtime is already gone inside frost_parse */
    }

    /* bc is valid even though the parse runtime is long destroyed */
    size_t sz = frost_bytecode_size(bc);
    CHECK(sz > 0);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    rc = frost_runtime_eval_loaded(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc);
}

/* -----------------------------------------------------------------------
 * B9 -- frost_runtime_load into bare runtime (with std_core)
 * ----------------------------------------------------------------------- */
static void test_B9(void)
{
    group("B9: load into bare runtime with std_core");

    frost_bytecode *bc = NULL;
    frost_parse("var bare_works = true;", "bare.js", &bc, NULL);
    CHECK_NOTNULL(bc);

    frost_runtime *rt = make_bare_with_core();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    rc = frost_runtime_eval_loaded(rt, bc, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc);
}

/* -----------------------------------------------------------------------
 * B10 -- frost_runtime_eval_loaded multiple times on same runtime
 * ----------------------------------------------------------------------- */
static void test_B10(void)
{
    group("B10: eval_loaded multiple times on same runtime");

    /* Use a simple source with no persistent side effects between evals */
    frost_bytecode *bc = NULL;
    frost_parse("(function(){var x=1;return x+1;})();", "multi.js", &bc, NULL);
    CHECK_NOTNULL(bc);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc, &err);
    CHECK_EQ(rc, 0);

    /* Eval 3 times -- should succeed each time */
    for (int i = 0; i < 3; i++) {
        err = NULL;
        rc = frost_runtime_eval_loaded(rt, bc, &err);
        CHECK_EQ(rc, 0);
        CHECK_NULL(err);
    }

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc);
}

/* -----------------------------------------------------------------------
 * B11 -- frost_runtime_load replaces previously loaded bytecode
 * ----------------------------------------------------------------------- */
static void test_B11(void)
{
    group("B11: load replaces previous load");

    frost_bytecode *bc1 = NULL;
    frost_bytecode *bc2 = NULL;
    frost_parse("var first = 1;", "first.js", &bc1, NULL);
    frost_parse("var second = 2;", "second.js", &bc2, NULL);
    CHECK_NOTNULL(bc1);
    CHECK_NOTNULL(bc2);

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_load(rt, bc1, &err);
    CHECK_EQ(rc, 0);

    /* Load again with different bytecode -- should free old and accept new */
    rc = frost_runtime_load(rt, bc2, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    /* Eval should run the second bytecode */
    rc = frost_runtime_eval_loaded(rt, bc2, &err);
    CHECK_EQ(rc, 0);
    CHECK_NULL(err);

    frost_runtime_destroy(rt);
    frost_bytecode_destroy(bc1);
    frost_bytecode_destroy(bc2);
}

/* -----------------------------------------------------------------------
 * B12 -- frost_runtime_eval_loaded before load (error)
 * ----------------------------------------------------------------------- */
static void test_B12(void)
{
    group("B12: eval_loaded before load returns error");

    frost_runtime *rt = make_full();
    CHECK_NOTNULL(rt);

    char *err = NULL;
    int rc = frost_runtime_eval_loaded(rt, NULL, &err);
    CHECK_EQ(rc, -1);
    CHECK_NOTNULL(err);
    free(err);

    frost_runtime_destroy(rt);
}

/* -----------------------------------------------------------------------
 * B13 -- frost_runtime_load NULL / bad args
 * ----------------------------------------------------------------------- */
static void test_B13(void)
{
    group("B13: frost_runtime_load NULL/bad-arg safety");

    /* Both NULL */
    char *err = NULL;
    int rc = frost_runtime_load(NULL, NULL, &err);
    CHECK_EQ(rc, -1);
    free(err);

    /* NULL err -- should not crash */
    rc = frost_runtime_load(NULL, NULL, NULL);
    CHECK_EQ(rc, -1);

    /* frost_runtime_eval_loaded NULL runtime */
    err = NULL;
    rc = frost_runtime_eval_loaded(NULL, NULL, &err);
    CHECK_EQ(rc, -1);
    free(err);
}

/* -----------------------------------------------------------------------
 * main
 * ----------------------------------------------------------------------- */
int main(void)
{
    printf("FrostCore Stage 3 -- Bytecode boundary tests\n");
    printf("=============================================\n");

    test_B1();
    test_B1b();
    test_B1c();
    test_B2();
    test_B3();
    test_B4();
    test_B5();
    test_B6();
    test_B7();
    test_B8();
    test_B9();
    test_B10();
    test_B11();
    test_B12();
    test_B13();

    printf("\n=============================================\n");
    printf("Results: %d passed, %d failed\n", g_pass, g_fail);

    return g_fail == 0 ? 0 : 1;
}
